CREATE OR REPLACE FUNCTION public.savings_account_before_runtime(p_record_id uuid, p_until date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.savings_balance_certifications%rowtype; ctx jsonb; schedule jsonb; end_date date; bal jsonb;
begin
 if auth.uid() is null or not public.has_admin_permission('savings.read') then raise exception 'SAVINGS_READ_DENIED' using errcode='42501'; end if;
 ctx:=public.savings_certification_context(p_record_id);
 select * into c from public.savings_balance_certifications where record_id=p_record_id;
 if not found then return jsonb_build_object('certified',false,'context',ctx,'today',public.savings_operation_today(),'can_confirm',public.has_admin_permission('savings.approve')); end if;
 end_date:=coalesce(p_until,greatest(public.savings_operation_today(),c.cutoff_on)+366);
 if end_date<c.cutoff_on or end_date>greatest(public.savings_operation_today(),c.cutoff_on)+1098 then raise exception 'SAVINGS_PROJECTION_RANGE_INVALID'; end if;
 select to_jsonb(b) into bal from public.savings_participant_balance(c.participant_id) b;
 select coalesce(jsonb_agg(jsonb_build_object('date',s.contribution_date,'expected',s.expected_amount,'actual',o.actual_amount,'version',coalesce(o.version_number,0),'confirmed',o.id is not null,'future',s.contribution_date>public.savings_operation_today()) order by s.contribution_date),'[]') into schedule
 from public.generate_savings_schedule(c.enrollment_id,c.cutoff_on+1,end_date) s
 left join lateral(select * from public.savings_contribution_overrides where enrollment_id=c.enrollment_id and contribution_date=s.contribution_date order by version_number desc limit 1)o on true;
 return jsonb_build_object('certified',true,'context',ctx,'certificate',to_jsonb(c)-array['command','source_snapshot','client_action_id'],'balance',bal,'schedule',schedule,
 'source_changed',(ctx->'snapshot'->'related') is distinct from (c.source_snapshot->'related'),
 'can_write',public.has_admin_permission('savings.write'),'can_confirm',public.has_admin_permission('savings.approve'),'publication','PRIVATE','today',public.savings_operation_today(),
 'balance_version',(select coalesce(max(id),0) from public.savings_audit_events where participant_id=c.participant_id),
 'projected_total',public.savings_panel_number(bal->'total')+coalesce((select sum((x->>'expected')::numeric) from jsonb_array_elements(schedule)x where x->>'future'='true'),0),
 'unconfirmed_dates',(select count(*) from jsonb_array_elements(schedule)x where x->>'future'='false' and x->>'confirmed'='false'),
 'history',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'at',a.created_at,'action',a.action,'observation',a.reason,'before',a.before_data,'after',a.after_data,'actor',coalesce(f.full_name,'Encargado autorizado')) order by a.id desc)
 from public.savings_audit_events a left join public.affiliates f on f.auth_user_id=a.actor_real_auth_user_id where a.participant_id=c.participant_id),'[]'));
end $function$

CREATE OR REPLACE FUNCTION public.savings_context_before_source_refresh(p_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.savings_review_records%rowtype; b public.savings_review_batches%rowtype;
 person jsonb; identity jsonb; links jsonb; related jsonb;
begin
 select * into r from public.savings_review_records where id=p_record_id and source_sheet='Ahorro';
 if not found then raise exception 'SAVINGS_RECORD_REQUIRED'; end if;
 select * into b from public.savings_review_batches where id=r.batch_id;
 select value into person from public.savings_panel_people(p_record_id) value;
 -- S is the currently approved amount; R is the original enrollment amount.
 person:=person||jsonb_build_object('aporte',case when r.proposed_data ? 'R' then public.savings_panel_number(r.proposed_data->'R') else coalesce(public.savings_panel_number(r.source_data->'S'),public.savings_panel_number(r.source_data->'R')) end,'plan_fin',public.savings_panel_date((r.source_data||r.proposed_data)->>'Z'));
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'control',numero_control,'archived',is_archived) order by id),'[]') into identity from public.affiliates where numero_control=r.source_folio;
 select coalesce(jsonb_agg(to_jsonb(p) order by p.id),'[]') into links from public.savings_participants p
 where legacy_folio=r.source_folio or affiliate_id in(select id from public.affiliates where numero_control=r.source_folio);
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'version',version,'source',source_data,'proposal',proposed_data,'status',status) order by id),'[]') into related
 from public.savings_review_records where source_folio=r.source_folio;
 return jsonb_build_object('person',person,'record_status',r.status,'source_version',r.version,'cutoff_on',(b.observed_at at time zone 'America/Hermosillo')::date,
 'snapshot',jsonb_build_object('batch_sha',b.source_sha256,'record_id',r.id,'source',r.source_data,'proposal',r.proposed_data,'related',related,'identity',identity,'participants',links,'historical_yield_through','2026-06-30'));
end $function$

CREATE OR REPLACE FUNCTION public.savings_certification_context(p_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; o public.savings_source_observations%rowtype; proposal jsonb; conflict boolean;
begin
 result:=public.savings_context_before_source_refresh(p_record_id);
 select * into o from public.savings_source_observations where record_id=p_record_id order by observed_at desc,id desc limit 1;
 if found then
  select proposed_data into proposal from public.savings_review_records where id=p_record_id;
  select exists(select 1 from jsonb_array_elements(o.changes)c where proposal ? (c->>'key') and proposal->(c->>'key') is distinct from c->'current') into conflict;
  result:=result||jsonb_build_object('source_update',jsonb_build_object('id',o.id,'source_total',o.source_total,'observed_at',o.observed_at,'changes',o.changes,
   'pending',not exists(select 1 from public.savings_source_acceptances where observation_id=o.id),'conflict',conflict),
   'can_accept_source_update',public.savings_review_edit_allowed());
  result:=jsonb_set(result,'{snapshot,source_observation}',jsonb_build_object('id',o.id,'sha',o.source_sha));
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.savings_financial_before_accounts(p_record_id uuid, p_until date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; snapshot jsonb;
begin
 result:=public.savings_account_before_runtime(p_record_id,p_until);
 if result->>'certified'='true' then
  result:=jsonb_set(result,'{balance_version}',to_jsonb(public.savings_balance_review_version(p_record_id)));
  select a.after_data->'source_snapshot' into snapshot from public.savings_audit_events a
  where a.participant_id=(result#>>'{certificate,participant_id}')::uuid and a.action='ADJUST_CONFIRMED_BALANCE' order by id desc limit 1;
  if snapshot is not null then result:=jsonb_set(result,'{source_changed}',to_jsonb((result#>'{context,snapshot,related}') is distinct from (snapshot->'related')));end if;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.get_admin_savings_financial_account(p_record_id uuid, p_until date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb; account jsonb;
begin
 base:=public.savings_financial_before_accounts(p_record_id,p_until);
 if base->>'certified'='true' then
  account:=public.get_admin_savings_account((base#>>'{certificate,participant_id}')::uuid,p_until);
  base:=base||jsonb_build_object('schedule',account->'schedule','balance',account->'balance','latest_enrollment',account->'latest_enrollment',
   'enrollments',account->'enrollments','projected_total',account->'projected_total','unconfirmed_dates',account->'unconfirmed_dates','history',account->'history','publication',account->'publication');
 end if;
 return base;
end $function$

CREATE OR REPLACE FUNCTION public.get_admin_savings_account(p_participant_id uuid, p_until date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.savings_participants%rowtype; c public.savings_balance_certifications%rowtype; en public.savings_enrollments%rowtype;
 plan public.savings_contribution_plans%rowtype; bal jsonb; schedule jsonb; history jsonb; identity jsonb; until_date date; start_date date; mode text; current_status text;
begin
 if auth.uid() is null or not public.has_admin_permission('savings.read') then raise exception 'SAVINGS_READ_DENIED' using errcode='42501';end if;
 select * into p from public.savings_participants where id=p_participant_id and data_classification='CANONICAL';
 if not found then raise exception 'SAVINGS_CANONICAL_ACCOUNT_REQUIRED';end if;
 select * into c from public.savings_balance_certifications where participant_id=p.id;
 select * into en from public.savings_enrollments where participant_id=p.id and data_classification='CANONICAL' order by sequence_number desc limit 1;
 current_status:=public.savings_enrollment_effective_status(en.status,en.terminated_at,public.savings_operation_today());
 until_date:=coalesce(p_until,public.savings_operation_today()+366);
 if until_date>public.savings_operation_today()+1098 or until_date<coalesce(c.cutoff_on,(p.created_at at time zone 'America/Hermosillo')::date) then raise exception 'SAVINGS_PROJECTION_RANGE_INVALID';end if;
 select coalesce(c.cutoff_on+1,min(first_expected_contribution_date),public.savings_operation_today()) into start_date from public.savings_enrollments where participant_id=p.id and data_classification='CANONICAL';
 select * into plan from public.savings_contribution_plans where enrollment_id=en.id and data_classification='CANONICAL'
  and (effective_to is null or effective_to>=public.savings_operation_today()) order by case when effective_from<=public.savings_operation_today() then 0 else 1 end,effective_from limit 1;
 select to_jsonb(b) into bal from public.savings_participant_balance(p.id)b;
 select coalesce(jsonb_agg(jsonb_build_object('enrollment_id',e.id,'date',s.contribution_date,'expected',s.expected_amount,
  'actual',o.actual_amount,'version',coalesce(o.version_number,0),'confirmed',o.id is not null,'future',s.contribution_date>public.savings_operation_today()) order by s.contribution_date,e.sequence_number),'[]') into schedule
 from public.savings_enrollments e cross join lateral public.generate_savings_schedule(e.id,greatest(start_date,e.first_expected_contribution_date),until_date)s
 left join lateral(select * from public.savings_contribution_overrides where enrollment_id=e.id and contribution_date=s.contribution_date order by version_number desc limit 1)o on true
 where e.participant_id=p.id and e.data_classification='CANONICAL' and e.first_expected_contribution_date<=until_date;
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'at',a.created_at,'action',a.action,'observation',a.reason,'before',a.before_data,'after',a.after_data,'actor','Encargado autorizado') order by a.id desc),'[]') into history
 from public.savings_audit_events a where a.participant_id=p.id;
 identity:=public.savings_review_identity(p.legacy_folio);
 select s.mode into mode from public.savings_publication_state s where id;
 return jsonb_build_object('participant_id',p.id,'certified',true,'native',c.id is null,
  'context',jsonb_build_object('person',jsonb_build_object('folio',p.legacy_folio,'nombre',identity->>'name','aporte',plan.amount,'inicio',(select min(first_actual_contribution_date) from public.savings_enrollments where participant_id=p.id and data_classification='CANONICAL'),
   'plan_inicio',(en.enrollment_started_at at time zone 'America/Hermosillo')::date,'estado',case when en.id is null then 'Por iniciar' when current_status='ACTIVE' then 'Ahorrando' when current_status='TERMINATED' then 'Dejo de ahorrar' else 'En revision' end,
   'frecuencia',case when plan.process_snapshot='JUB' then 'MONTHLY' else 'TWICE_MONTHLY' end,'identity',identity),'cutoff_on',c.cutoff_on),
  'balance',bal,'latest_enrollment',to_jsonb(en)||jsonb_build_object('status',current_status,'recorded_status',en.status),'schedule',schedule,'history',history,'today',public.savings_operation_today(),'publication',mode,
  'enrollments',coalesce((select jsonb_agg(to_jsonb(e) order by sequence_number desc) from public.savings_enrollments e where participant_id=p.id and data_classification='CANONICAL'),'[]'),
  'can_confirm',false,'can_write',public.has_admin_permission('savings.write') and (identity->>'match_count')::int=1 and (identity->>'active_match_count')::int=1
   and exists(select 1 from public.affiliates a where a.id=p.affiliate_id and a.numero_control=p.legacy_folio and not coalesce(a.is_archived,false)),
  'unconfirmed_dates',(select count(*) from jsonb_array_elements(schedule)x where x->>'future'='false' and x->>'confirmed'='false'),
  'projected_total',(bal->>'total')::numeric+coalesce((select sum((x->>'expected')::numeric) from jsonb_array_elements(schedule)x where x->>'future'='true'),0),
  'balance_version',md5(jsonb_build_array(p.id,bal,(select coalesce(max(id),0) from public.savings_audit_events where participant_id=p.id))::text));
end $function$
